const char lab_web_index[] = R"HTML(
<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#061422">
<title>ESP32 LAB // FUTURE CONTROL</title>
<style>
:root{--bg:#06111d;--panel:#0a1b2b;--panel2:#0e2540;--line:#1a3d59;--txt:#eef8ff;--mut:#8da9bf;--cyan:#45e6ff;--blue:#5c8fff;--ok:#31e7a5;--warn:#ffca52;--bad:#ff5879;--vio:#bd7cff;--shadow:0 18px 60px rgba(0,0,0,.34);--r:24px}
[data-theme="light"]{--bg:#eaf2f8;--panel:#fff;--panel2:#eef7ff;--line:#c6dae8;--txt:#0b2030;--mut:#587086;--cyan:#0aa4d6;--blue:#3d6fe8;--shadow:0 15px 40px rgba(30,70,100,.16)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(1200px 600px at 50% -250px,#15527d44,transparent),var(--bg);color:var(--txt);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;min-height:100vh}
button,input{font:inherit}.app{max-width:1280px;margin:auto;padding:12px 14px 44px}.top{position:sticky;top:8px;z-index:20;background:color-mix(in srgb,var(--panel) 88%,transparent);backdrop-filter:blur(18px);border:1px solid var(--line);border-radius:26px;padding:12px 14px;box-shadow:var(--shadow);display:flex;align-items:center;justify-content:space-between;gap:10px}.brand{display:flex;align-items:center;gap:12px}.orb{width:42px;height:42px;border-radius:50%;background:conic-gradient(from 0deg,var(--cyan),var(--blue),var(--vio),var(--cyan));box-shadow:0 0 35px #45e6ff2a;animation:spin 5s linear infinite}.brand b{font-size:17px}.small{font-size:11px;color:var(--mut)}.pill{display:inline-flex;align-items:center;gap:5px;padding:7px 10px;border-radius:999px;background:var(--panel2);border:1px solid var(--line);font-size:11px;font-weight:850}.ok{color:var(--ok);border-color:#1d7257}.warn{color:var(--warn);border-color:#765e26}.bad{color:var(--bad);border-color:#7b2d45}.vio{color:var(--vio);border-color:#633d8e}
.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:12px;margin-top:12px}.card{grid-column:span 12;background:linear-gradient(180deg,var(--panel),color-mix(in srgb,var(--panel) 86%,#08223a));border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow);padding:16px}.half{grid-column:span 6}.third{grid-column:span 4}.title{display:flex;justify-content:space-between;gap:10px;align-items:center}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.btn{appearance:none;border:1px solid #235579;background:linear-gradient(180deg,#123455,#0c2742);color:var(--txt);padding:10px 13px;border-radius:14px;font-weight:850;cursor:pointer;transition:.14s transform,.14s filter,.14s box-shadow}.btn:hover{filter:brightness(1.12);box-shadow:0 0 24px #45e6ff12}.btn:active{transform:scale(.97)}.btn.cyan{border-color:#227b8c;color:#cffaff}.btn.ok{border-color:#23775d;color:#caffeb}.btn.vio{border-color:#6a4094}.btn.bad{border-color:#7d2d48}.btn.ghost{background:transparent}.metricGrid{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin-top:12px}.metric{background:var(--panel2);border:1px solid var(--line);border-radius:18px;padding:12px}.metric .v{font-size:23px;font-weight:950;margin-top:4px}.metric .k{font-size:10px;text-transform:uppercase;letter-spacing:.09em;color:var(--mut)}
.workers{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px}.wc{background:var(--panel2);border:1px solid var(--line);border-radius:21px;padding:13px;min-height:210px;position:relative;overflow:hidden}.wc.live:before{content:"";position:absolute;inset:-40%;background:radial-gradient(circle,#45e6ff13,transparent 55%);animation:pulse 2.4s ease-in-out infinite}.whead{display:flex;align-items:center;justify-content:space-between;position:relative;z-index:2}.gauge{width:106px;height:106px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--cyan) calc(var(--p)*1%),#17324d 0);position:relative;box-shadow:0 0 30px #45e6ff14;margin:11px auto}.gauge:after{content:"";position:absolute;inset:10px;background:var(--panel);border:1px solid var(--line);border-radius:50%}.gauge b{position:relative;z-index:2;font-size:21px}.wmeta{display:grid;grid-template-columns:1fr 1fr;gap:7px}.chip{background:rgba(0,0,0,.12);border:1px solid var(--line);border-radius:12px;padding:7px}.chip b{display:block;font-size:12px}.bar{height:7px;background:#173149;border-radius:999px;overflow:hidden}.bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--blue),var(--cyan));transition:width .35s}.chart{height:150px;width:100%;display:block}.jobs{display:grid;gap:8px;margin-top:12px}.job{display:grid;grid-template-columns:60px 1fr auto;gap:11px;align-items:center;background:var(--panel2);border:1px solid var(--line);border-radius:17px;padding:10px}.job .id{font-size:22px;font-weight:950}.job .type{font-weight:850}.job .sub{font-size:11px;color:var(--mut);margin-top:3px}.job .pr{font-size:11px;color:var(--cyan)}.console{font:12px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace;background:#03101b;color:#cbeaff;border:1px solid #173550;border-radius:17px;padding:12px;min-height:180px;max-height:330px;overflow:auto;white-space:pre-wrap}.folderGrid{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;margin-top:12px}.folder{background:var(--panel2);border:1px solid var(--line);border-radius:16px;padding:13px;cursor:pointer;transition:.14s}.folder:hover{transform:translateY(-1px)}.folder .ico{font-size:24px}.mut{color:var(--mut)}.hide{display:none!important}.kbd{padding:3px 7px;border:1px solid var(--line);border-radius:7px;background:var(--panel2);font:11px ui-monospace}.toast{position:fixed;right:14px;bottom:14px;z-index:80;max-width:360px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--shadow);border-radius:16px;padding:12px 14px;opacity:0;transform:translateY(15px);pointer-events:none;transition:.18s}.toast.show{opacity:1;transform:none}.cmd{position:fixed;inset:0;background:#0008;backdrop-filter:blur(8px);display:grid;place-items:start center;padding-top:12vh;z-index:90}.cmd>div{width:min(720px,calc(100vw - 28px));background:var(--panel);border:1px solid var(--line);border-radius:24px;box-shadow:var(--shadow);padding:14px}.cmd input{font-size:18px}.cmdRow{padding:10px;border-radius:12px;border:1px solid transparent;cursor:pointer}.cmdRow:hover{background:var(--panel2);border-color:var(--line)}
@keyframes pulse{50%{transform:scale(1.08);opacity:.6}}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:980px){.workers{grid-template-columns:1fr 1fr}.metricGrid{grid-template-columns:repeat(3,1fr)}.folderGrid{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.half,.third{grid-column:span 12}.workers{grid-template-columns:1fr}.metricGrid{grid-template-columns:repeat(2,1fr)}.folderGrid{grid-template-columns:repeat(2,1fr)}.top{top:4px}.app{padding:8px}.job{grid-template-columns:48px 1fr}.job button{grid-column:2}.orb{width:34px;height:34px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}
</style>
</head>
<body>
<div class="app">
<header class="top"><div class="brand"><div class="orb"></div><div><b>ESP32 LAB // FUTURE CONTROL</b><div class="small">orchestration locale • workers • OTA • SD • diagnostics</div></div></div><div class="actions" style="margin:0"><span id="conn" class="pill warn">LOCAL</span><button class="btn ghost" onclick="toggleTheme()">☀︎/☾</button><button class="btn ghost" onclick="openCmd()">⌘K</button></div></header>

<div class="grid">
<section class="card">
  <div class="title"><div><h2 style="margin:0">Centre de commandement</h2><div class="small">Le laboratoire orchestre les workers sans dépendre du navigateur.</div></div><span id="masterState" class="pill ok">READY</span></div>
  <div class="actions">
    <button class="btn cyan" onclick="createJob('PING',10)">◉ PING</button>
    <button class="btn" onclick="createJob('SYSTEM_TEST',50)">🧪 CHECK-UP</button>
    <button class="btn vio" onclick="createJob('BENCHMARK',70)">⚡ BENCHMARK</button>
    <button class="btn ok" onclick="createJob('FS_TEST',60)">💾 FS TEST</button>
    <button class="btn cyan" onclick="turboAll()">🚀 TURBO ALL</button>
    <button class="btn vio" onclick="benchmarkAll()">📈 BENCH FLEET</button>
    <button class="btn ok" onclick="stressGrid()">🧠 STRESS ×9</button>
    <button class="btn" onclick="mission()">🛰️ MISSION</button>
    <button class="btn bad" onclick="cancelAll()">⛔ STOP ALL</button>
  </div>
  <div class="metricGrid">
    <div class="metric"><div class="k">Workers</div><div id="mWorkers" class="v">0</div></div>
    <div class="metric"><div class="k">CPU master</div><div id="mCpu" class="v">—</div></div>
    <div class="metric"><div class="k">Heap</div><div id="mHeap" class="v">—</div></div>
    <div class="metric"><div class="k">PSRAM</div><div id="mPsram" class="v">—</div></div>
    <div class="metric"><div class="k">DHT11</div><div id="mEnv" class="v">—</div></div>
  </div>
</section>

<section class="card"><div class="title"><div><h3 style="margin:0">Télémétrie en direct</h3><div class="small">Historique côté navigateur pour visualiser la stabilité.</div></div><span id="ws" class="pill">WS —</span></div><canvas id="chart" class="chart" width="1200" height="150"></canvas></section>

<section class="card"><div class="title"><div><h3 style="margin:0">WORKER POOL</h3><div class="small">CPU • RAM • RSSI • flash • progression • état</div></div><span id="pool" class="pill">0 actifs</span></div><div id="workers" class="workers"></div></section>

<section class="card half"><div class="title"><div><h3 style="margin:0">Jobs / scheduler</h3><div class="small">priorité • retries • durée • annulation</div></div><span id="queue" class="pill">0</span></div><div id="jobs" class="jobs"><div class="mut">chargement…</div></div></section>

<section class="card half"><div class="title"><div><h3 style="margin:0">Console multi-worker</h3><div class="small">UDP logs + événements du MASTER</div></div><button class="btn ghost" onclick="refreshLogs()">↻</button></div><pre id="logs" class="console">connexion…</pre></section>

<section class="card"><div class="title"><div><h3 style="margin:0">Navigation SD</h3><div class="small">Exploration rapide des espaces du LAB</div></div></div><div class="folderGrid">
 <div class="folder" onclick="sd('/sd/PROJECTS')"><div class="ico">📁</div><b>Projets</b><div class="small">PREPARED / IMPORTED</div></div>
 <div class="folder" onclick="sd('/sd/FIRMWARE')"><div class="ico">⚡</div><b>Firmware</b><div class="small">MASTER / WORKER / AVR</div></div>
 <div class="folder" onclick="sd('/sd/COMPONENTS')"><div class="ico">🧩</div><b>Composants</b><div class="small">catalogue extensible</div></div>
 <div class="folder" onclick="sd('/sd/TESTS')"><div class="ico">🧪</div><b>Tests</b><div class="small">traces et diagnostics</div></div>
 <div class="folder" onclick="sd('/sd/REPORTS')"><div class="ico">📊</div><b>Rapports</b><div class="small">snapshot / JSON / TXT</div></div>
 <div class="folder" onclick="sd('/sd/AI')"><div class="ico">🧠</div><b>AI</b><div class="small">mémoire opérationnelle</div></div>
</div></section>

<section class="card"><div class="title"><div><h3 style="margin:0">Firmware / OTA</h3><div class="small">SHA-256 • téléchargement • approbation contrôlée</div></div><span id="ota" class="pill">READY</span></div><div class="actions"><button class="btn" onclick="checkUpdate()">Vérifier une release</button><button class="btn cyan" onclick="approveUpdate()">Approuver OTA</button><button class="btn bad" onclick="scrollFlash()">Flash Worker</button></div><div id="otaBox" class="console" style="margin-top:10px;min-height:70px">aucune opération OTA</div></section>

<section class="card"><div class="title"><div><h3 style="margin:0">Agent technique</h3><div class="small">question → analyse → plan d'action ; flash/OTA restent confirmables</div></div></div><div class="actions"><input id="agentQ" placeholder="Ex: lance un check-up puis explique les RAM / RSSI" style="flex:1;min-width:240px;background:var(--panel2);border:1px solid var(--line);color:var(--txt);padding:11px;border-radius:14px"><button class="btn cyan" onclick="agentAsk()">Analyser</button></div><pre id="agentA" class="console" style="margin-top:10px">—</pre></section>

<section class="card" id="flash"><div class="title"><div><h3 style="margin:0">Atelier Flash</h3><div class="small">Worker ESP32 ou AVR depuis la SD</div></div></div><div class="actions"><input id="workerPath" value="/sd/FIRMWARE/WORKER/ESP32_LAB_WORKER.bin" style="flex:1;min-width:260px;background:var(--panel2);border:1px solid var(--line);color:var(--txt);padding:11px;border-radius:14px"><select id="workerId" style="width:120px;background:var(--panel2);border:1px solid var(--line);color:var(--txt);padding:11px;border-radius:14px"><option>1</option><option>2</option><option>3</option></select><button class="btn bad" onclick="flashWorker()">Flasher</button></div><pre id="flashOut" class="console" style="margin-top:10px">prêt</pre></section>

<section class="card"><div class="title"><div><h3 style="margin:0">Raccourcis</h3><div class="small">Appuie sur <span class="kbd">Ctrl</span> + <span class="kbd">K</span> pour la palette. Les animations respectent le mode réduit du navigateur.</div></div></div></section>
</div>
</div>
<div id="toast" class="toast"></div>
<div id="cmd" class="cmd hide"><div><input id="cmdInput" placeholder="Tape une commande…" style="width:100%;background:var(--panel2);border:1px solid var(--line);color:var(--txt);padding:13px;border-radius:15px"><div id="cmdList" style="margin-top:8px"></div></div></div>
<script>
const $=id=>document.getElementById(id); let ws=null,poll=null; const hist=[]; const maxHist=90;
const commands=[['PING worker pool','createJob(\'PING\',10)'],['Check-up complet','createJob(\'SYSTEM_TEST\',50)'],['Benchmark CPU','createJob(\'BENCHMARK\',70)'],['Test LittleFS','createJob(\'FS_TEST\',60)'],['Turbo tous les workers','turboAll()'],['Benchmark flotte','benchmarkAll()'],['Stress test x9','stressGrid()'],['Mission laboratoire','mission()'],['Stopper tous les jobs','cancelAll()'],['Theme clair/sombre','toggleTheme()'],['Aller au flash','#flash']];
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2300)}
async function api(url,opt={}){try{let r=await fetch(url,opt);let t=await r.text();let j;try{j=JSON.parse(t)}catch{j={raw:t,status:r.status}};if(r.status>=400) toast('HTTP '+r.status);return j}catch(e){toast('Connexion perdue');return{error:String(e)}}}
function theme(){document.documentElement.dataset.theme=localStorage.labTheme||'dark'} function toggleTheme(){localStorage.labTheme=localStorage.labTheme==='light'?'dark':'light';theme();paintChart()}
theme();
function workerCard(w){let p=w.progress||0;let live=w.state!=='OFFLINE';let ram=Math.round((w.heap||0)/1024);let flash=Math.round((w.flash_size||0)/1048576);return `<div class="wc ${live?'live':''}"><div class="whead"><b>W${w.id}</b><span class="pill ${w.state==='READY'?'ok':(w.state==='OFFLINE'?'bad':'warn')}">${w.state}</span></div><div class="gauge" style="--p:${p}"><b>${p}%</b></div><div class="wmeta"><div class="chip"><span class="small">CPU</span><b>${w.cpu_mhz||'—'} MHz × ${w.cores||'—'}</b></div><div class="chip"><span class="small">RAM</span><b>${ram} KB</b></div><div class="chip"><span class="small">RSSI</span><b>${w.rssi??'—'} dBm</b></div><div class="chip"><span class="small">FLASH</span><b>${flash} MB</b></div></div><div class="small" style="margin-top:8px">${w.ip||'—'} • ${w.mac||'—'}<br>${w.job||'idle'} • v${w.version||'—'}</div><div class="actions" style="margin-top:7px"><button class="btn ghost" onclick="workerJob(${w.id},'PING',10)">PING</button><button class="btn ghost" onclick="workerJob(${w.id},'BENCHMARK',70)">BENCH</button><button class="btn ghost" onclick="rebootWorker(${w.id})">REBOOT</button></div></div>`}
function render(s){let m=s.master||{}; $('conn').textContent=m.internet?'INTERNET':'LOCAL';$('conn').className='pill '+(m.internet?'ok':'warn');$('masterState').textContent=m.state||'READY';$('mWorkers').textContent=(s.workers||[]).filter(w=>w.state!=='OFFLINE').length+'/'+(s.workers||[]).length;$('mCpu').textContent=(m.cpu_mhz||'—')+' MHz';$('mHeap').textContent=Math.round((m.heap||0)/1024)+' KB';$('mPsram').textContent=Math.round((m.psram||0)/1024)+' KB';$('mEnv').textContent=(m.temp??'—')+'° / '+(m.humidity??'—')+'%';let a=s.workers||[];$('pool').textContent=a.filter(w=>w.state!=='OFFLINE').length+' actifs';$('workers').innerHTML=a.length?a.map(workerCard).join(''):'<div class="mut">Aucun worker détecté.</div>';hist.push({t:Date.now(),heap:m.heap||0,temp:m.temp||0,workers:a.filter(w=>w.state!=='OFFLINE').length});while(hist.length>maxHist)hist.shift();paintChart()}
function paintChart(){let c=$('chart'),ctx=c.getContext('2d'),r=devicePixelRatio||1,w=c.clientWidth||1200,h=150;c.width=w*r;c.height=h*r;ctx.setTransform(r,0,0,r,0,0);ctx.clearRect(0,0,w,h);if(!hist.length)return;let vals=hist.map(x=>x.heap/1024),min=Math.min(...vals),max=Math.max(...vals);if(max-min<1){max=min+1}ctx.globalAlpha=.9;ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--cyan').trim();ctx.lineWidth=2;ctx.beginPath();vals.forEach((v,i)=>{let x=10+(w-20)*(i/(Math.max(1,vals.length-1)));let y=h-18-(h-35)*(v-min)/(max-min);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--mut').trim();ctx.font='11px system-ui';ctx.fillText('Heap master (KB)',10,14);ctx.fillText(Math.round(max)+' KB',w-80,14)}
async function refresh(){let s=await api('/api/state');if(s.master)render(s);let j=await api('/api/jobs');renderJobs(j);refreshLogs()}
function renderJobs(j){let a=Array.isArray(j)?j:[];$('queue').textContent=a.length;$('jobs').innerHTML=a.length?a.slice().reverse().map(x=>{let can=x.status==='QUEUED'||x.status==='RUNNING';return `<div class="job"><div class="id">#${x.id}</div><div><div class="type">${x.type} <span class="pr">P${x.priority}</span></div><div class="sub">${x.status} • W${x.worker||'—'} • ${x.progress||0}% • retry ${x.retries||0}</div><div class="bar" style="margin-top:7px"><i style="width:${x.progress||0}%"></i></div></div>${can?`<button class="btn bad" onclick="cancelJob(${x.id})">Annuler</button>`:'<span class="small">terminé</span>'}</div>`}).join(''):'<div class="mut">Aucun job.</div>'}
async function refreshLogs(){let x=await api('/api/logs');$('logs').textContent=x.raw||''}
async function createJob(t,p=5){let r=await api('/api/job',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'type='+encodeURIComponent(t)+'&priority='+p});if(r.accepted)toast('Job #'+r.id+' ajouté');refresh()}
async function workerJob(id,t,p){toast('W'+id+' → '+t);await createJob(t,p)}
async function cancelJob(id){let r=await api('/api/job/cancel',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'id='+id});toast(r.ok?'Job annulé':'Annulation refusée');refresh()}
async function cancelAll(){let r=await api('/api/jobs/cancel-all',{method:'POST'});toast('STOP ALL : '+(r.cancelled??0)+' job(s)');refresh()}
async function turboAll(){await Promise.all([createJob('SYSTEM_TEST',90),createJob('SYSTEM_TEST',90),createJob('SYSTEM_TEST',90)]);toast('TURBO ALL lancé');}
async function benchmarkAll(){await Promise.all([createJob('BENCHMARK',95),createJob('BENCHMARK',95),createJob('BENCHMARK',95)]);toast('BENCH FLEET lancé');}
async function stressGrid(){for(const t of ['SYSTEM_TEST','BENCHMARK','FS_TEST','SYSTEM_TEST','BENCHMARK','FS_TEST','SYSTEM_TEST','BENCHMARK','FS_TEST'])await createJob(t,t==='BENCHMARK'?96:80);toast('STRESS ×9 lancé');}
async function rebootWorker(id){let r=await api('/api/worker/reboot',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'id='+id});toast(r.ok?'W'+id+' redémarrage demandé':'W'+id+' redémarrage refusé');setTimeout(refresh,1200)}
async function mission(){for(const t of ['PING','SYSTEM_TEST','BENCHMARK','FS_TEST'])await createJob(t,t==='BENCHMARK'?75:55);toast('Mission laboratoire envoyée')}
async function sd(path){let x=await api('/api/sd/list?path='+encodeURIComponent(path));$('logs').textContent=JSON.stringify(x,null,2)}
function scrollFlash(){$('flash').scrollIntoView({behavior:'smooth'})}
async function flashWorker(){let id=$('workerId').value,p=$('workerPath').value;let r=await api('/api/worker/flash',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({id,path:p})});$('flashOut').textContent=JSON.stringify(r,null,2);toast(r.ok?'Flash demandé':'Flash refusé')}
async function checkUpdate(){let r=await api('/api/update/check',{method:'POST'});$('otaBox').textContent=JSON.stringify(r,null,2);$('ota').textContent=r.available?'UPDATE':'NO UPDATE'}
async function approveUpdate(){let r=await api('/api/update/approve',{method:'POST'});$('otaBox').textContent=JSON.stringify(r,null,2)}
async function agentAsk(){let q=$('agentQ').value||'Donne un diagnostic global du laboratoire';let r=await api('/api/agent/chat',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'q='+encodeURIComponent(q)});$('agentA').textContent=r.answer||r.error||JSON.stringify(r,null,2)}
function openCmd(){ $('cmd').classList.remove('hide');$('cmdInput').value='';drawCmd();setTimeout(()=>$('cmdInput').focus(),20)} function closeCmd(){ $('cmd').classList.add('hide') } function drawCmd(){let q=$('cmdInput').value.toLowerCase();$('cmdList').innerHTML=commands.filter(c=>c[0].toLowerCase().includes(q)).map(c=>`<div class="cmdRow" onclick="runCmd(${JSON.stringify(c[1])})">${c[0]} <span class="small">${c[1]}</span></div>`).join('')}
function runCmd(code){closeCmd();if(code==='#flash'){scrollFlash();return}try{eval(code)}catch(e){toast('Commande: '+e.message)}}$('cmdInput').addEventListener('input',drawCmd);$('cmd').addEventListener('click',e=>{if(e.target.id==='cmd')closeCmd()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCmd()}if(e.key==='Escape')closeCmd()});
function connect(){try{ws=new WebSocket(`ws://${location.host}/ws`);ws.onopen=()=>{$('ws').textContent='WS OK';$('ws').className='pill ok'};ws.onmessage=e=>{try{render(JSON.parse(e.data))}catch{}};ws.onclose=()=>{$('ws').textContent='WS reconnect';$('ws').className='pill warn';startPoll();setTimeout(connect,1600)}}catch{startPoll()}}
function startPoll(){if(!poll)poll=setInterval(refresh,4500)}
window.addEventListener('resize',paintChart);refresh();connect();startPoll();
</script></body></html>
)HTML";
